# Triad Drift - scatter kit: cheap meshes the planet scatter (T4, ATDTerrainScatter) instances by the thousand.
# Engineering-made (ArtSource/EngProps). Everything is generated by code; no AI mesh, no third-party asset.
#
# Run headless from the repo root:
#   blender --background --factory-startup --python ArtSource/EngProps/Scatter/scripts/build_scatter.py
#
# Writes, per asset, ArtSource/EngProps/Scatter/<Name>/<Name>.blend + .fbx + .manifest.json, the shared
# 512 px atlas in textures/ (T_Scatter_Atlas_BC / _E) and review sheets in review/.
#
# How the meshes are coloured (no per-asset texture):
#   - Foliage, canopy and charred trees use ONE 512 x 512 atlas. Its left quarter is 8 vertical colour ramps
#     (root -> tip); every vertex sits on the centre line of one ramp with V = how far up the plant it is.
#     The right three quarters are a tiling charred-bark pattern with ember cracks (charred trees).
#   - Boulders have no texture of their own: Unreal projects the terrain's rock set onto them in world space.

import json
import math
import os
import random
import runpy
import sys

import bmesh
import bpy
import numpy as np
from mathutils import Matrix, Vector, noise

HERE = os.path.dirname(os.path.abspath(__file__))
KIT = os.path.dirname(HERE)
REPO = os.path.abspath(os.path.join(KIT, "..", "..", ".."))
SKILLS = os.path.join(REPO, ".claude", "skills")
TEX_DIR = os.path.join(KIT, "textures")
REVIEW = os.path.join(KIT, "review")
UP = Vector((0, 0, 1))

ATLAS = 512
RAMPS = 8                      # ramps live in u = 0 .. 0.25
BARK_U0 = 0.25                 # bark pattern lives in u = 0.25 .. 1


def ramp_u(i):
    return (i + 0.5) / (RAMPS * 4.0)


