def _srgb(x):
    x = np.clip(x, 0.0, 1.0)
    return np.where(x <= 0.0031308, x * 12.92, 1.055 * np.power(x, 1.0 / 2.4) - 0.055)


def _ramp(stops, n, which):
    pos = np.array([s[0] for s in stops])
    out = np.zeros((n, 3))
    t = (np.arange(n) + 0.5) / n
    for c in range(3):
        out[:, c] = np.interp(t, pos, np.array([s[which][c] for s in stops]))
    return out


def _tile_noise(rng, w, h, cells_x, cells_y, octaves=3):
    """Value noise that tiles in both directions."""
    total = np.zeros((h, w))
    amp = 1.0
    for o in range(octaves):
        cx, cy = cells_x * 2 ** o, cells_y * 2 ** o
        grid = rng.random((cy, cx))
        xs = (np.arange(w) + 0.5) / w * cx
        ys = (np.arange(h) + 0.5) / h * cy
        x0 = np.floor(xs).astype(int) % cx
        y0 = np.floor(ys).astype(int) % cy
        fx = xs - np.floor(xs)
        fy = ys - np.floor(ys)
        fx = fx * fx * (3 - 2 * fx)
        fy = fy * fy * (3 - 2 * fy)
        x1 = (x0 + 1) % cx
        y1 = (y0 + 1) % cy
        a = grid[np.ix_(y0, x0)]
        b = grid[np.ix_(y0, x1)]
        c = grid[np.ix_(y1, x0)]
        d = grid[np.ix_(y1, x1)]
        total += amp * ((a * (1 - fx) + b * fx) * (1 - fy)[:, None] + (c * (1 - fx) + d * fx) * fy[:, None])
        amp *= 0.5
    return total / (2.0 - 0.5 ** (octaves - 1))


def _tile_cracks(rng, w, h, cells_x, cells_y):
    """Tiling Voronoi: returns (edge distance F2 - F1, per-cell random value)."""
    px = (rng.random((cells_y, cells_x)) * 0.8 + 0.1 + np.arange(cells_x)[None, :]) / cells_x
    py = (rng.random((cells_y, cells_x)) * 0.8 + 0.1 + np.arange(cells_y)[:, None]) / cells_y
    val = rng.random((cells_y, cells_x))
    xs = ((np.arange(w) + 0.5) / w)[None, :]
    ys = ((np.arange(h) + 0.5) / h)[:, None]
    f1 = np.full((h, w), 9.0)
    f2 = np.full((h, w), 9.0)
    cell = np.zeros((h, w))
    aspect = h / float(w)
    for j in range(cells_y):
        for i in range(cells_x):
            dx = np.abs(xs - px[j, i])
            dx = np.minimum(dx, 1.0 - dx)
            dy = np.abs(ys - py[j, i])
            dy = np.minimum(dy, 1.0 - dy) * aspect
            d = np.sqrt(dx * dx + dy * dy)
            closer = d < f1
            f2 = np.where(closer, f1, np.minimum(f2, d))
            cell = np.where(closer, val[j, i], cell)
            f1 = np.where(closer, d, f1)
    return f2 - f1, cell


def build_atlas():
    os.makedirs(TEX_DIR, exist_ok=True)
    bc = np.zeros((ATLAS, ATLAS, 3))
    em = np.zeros((ATLAS, ATLAS, 3))
    col_w = ATLAS // (RAMPS * 4)
    for i, stops in enumerate(RAMP_DEF):
        bc[:, i * col_w:(i + 1) * col_w, :] = _ramp(stops, ATLAS, 1)[:, None, :]
        em[:, i * col_w:(i + 1) * col_w, :] = _ramp(stops, ATLAS, 2)[:, None, :]
    # Charred bark: long vertical plates split by cracks; some cracks still burn.
    rng = np.random.default_rng(20261113)
    x0 = int(ATLAS * BARK_U0)
    w = ATLAS - x0
    edge, cell = _tile_cracks(rng, w, ATLAS, 10, 5)
    grain = _tile_noise(rng, w, ATLAS, 24, 6, 3)
    broad = _tile_noise(rng, w, ATLAS, 3, 3, 2)
    crack = 1.0 - np.clip(edge / 0.011, 0, 1)            # 1 on a crack line
    crack_core = 1.0 - np.clip(edge / 0.004, 0, 1)
    plate = 0.012 + 0.050 * cell * cell + 0.030 * grain          # charcoal to ash grey
    base = plate[:, :, None] * np.array([1.0, 0.95, 0.92])[None, None, :]
    base = base * (1.0 - 0.9 * np.clip(1.0 - edge / 0.02, 0, 1)[:, :, None])
    hot = np.clip((broad - 0.56) / 0.16, 0, 1)            # only some regions still burn
    glow = crack * hot
    core = crack_core * hot
    ember = glow[:, :, None] * np.array([0.90, 0.16, 0.015])[None, None, :] + core[:, :, None] * np.array([0.60, 0.45, 0.10])[None, None, :]
    base = base + glow[:, :, None] * np.array([0.25, 0.04, 0.0])[None, None, :]
    bc[:, x0:, :] = base
    em[:, x0:, :] = np.clip(ember, 0, 1)

    paths = {}
    for suffix, arr in (("BC", bc), ("E", em)):
        name = "T_Scatter_Atlas_" + suffix
        old = bpy.data.images.get(name)
        if old is not None:
            bpy.data.images.remove(old)
        img = bpy.data.images.new(name, ATLAS, ATLAS, alpha=False)
        rgba = np.ones((ATLAS, ATLAS, 4), dtype=np.float32)
        rgba[:, :, :3] = _srgb(arr)
        img.pixels.foreach_set(rgba.reshape(-1))
        path = os.path.join(TEX_DIR, name + ".png")
        img.filepath_raw = path
        img.file_format = "PNG"
        img.save()
        paths[suffix] = path
    return paths


def make_materials(paths):
    mat = bpy.data.materials.new("M_Scatter_Atlas")
    nt = mat.node_tree
    bsdf = next(n for n in nt.nodes if n.type == "BSDF_PRINCIPLED")
    for suffix, sock in (("BC", "Base Color"), ("E", "Emission Color")):
        node = nt.nodes.new("ShaderNodeTexImage")
        node.image = bpy.data.images.load(paths[suffix], check_existing=True)
        node.interpolation = "Linear"
        nt.links.new(node.outputs["Color"], bsdf.inputs[sock])
    bsdf.inputs["Emission Strength"].default_value = 2.0
    bsdf.inputs["Roughness"].default_value = 0.7
    mat.use_backface_culling = False
    rock = bpy.data.materials.new("M_Scatter_Rock")
    rb = next(n for n in rock.node_tree.nodes if n.type == "BSDF_PRINCIPLED")
    rb.inputs["Base Color"].default_value = (0.11, 0.115, 0.12, 1.0)
    rb.inputs["Roughness"].default_value = 0.85
    return mat, rock


# ---------------------------------------------------------------------------------------------- geometry
class Geo:
    def __init__(self):
        self.v = []
        self.f = []
        self.uv = []

    def vert(self, p):
        self.v.append(Vector(p))
        return len(self.v) - 1

    def face(self, idx, uvs):
        self.f.append(tuple(idx))
        self.uv.append([tuple(u) for u in uvs])

    def tris(self):
        return sum(len(f) - 2 for f in self.f)

    def build(self, name, mat, smooth=False, sharp_deg=None, up_blend=0.0):
        me = bpy.data.meshes.new(name)
        me.from_pydata([tuple(p) for p in self.v], [], self.f)
        me.update()
        layer = me.uv_layers.new(name="UVMap")
        for poly, uvs in zip(me.polygons, self.uv):
            for k, li in enumerate(poly.loop_indices):
                layer.data[li].uv = uvs[k]
        me.materials.append(mat)
        if smooth:
            me.shade_smooth()
            if sharp_deg is not None:
                me.set_sharp_from_angle(angle=math.radians(sharp_deg))
        else:
            me.shade_flat()
        if up_blend > 0.0:
            # Foliage trick: lean every normal toward straight up, so thin blades are lit like the ground
            # they stand on instead of flickering light / dark with their own facing.
            normals = []
            for poly in me.polygons:
                n = poly.normal
                if n.z < 0:
                    n = -n
                n = (n * (1.0 - up_blend) + UP * up_blend).normalized()
                normals.extend([tuple(n)] * poly.loop_total)
            me.normals_split_custom_set(normals)
        obj = bpy.data.objects.new(name, me)
        bpy.context.scene.collection.objects.link(obj)
        return obj


def blade(g, base, yaw, length, width, lean, curve, segs, col, t0=0.0, t1=1.0, taper=0.8, face_yaw=None):
    """A tapered strip that grows up from `base`, leaning toward `yaw`; ends in a point. 2*segs-1 triangles."""
    d = Vector((math.cos(yaw), math.sin(yaw), 0.0))
    fy = yaw if face_yaw is None else face_yaw
    w = Vector((-math.sin(fy), math.cos(fy), 0.0))
    p = Vector(base)
    ang = lean
    u = ramp_u(col)
    rows = []
    for i in range(segs + 1):
        f = i / float(segs)
        wd = width * (1.0 - f) ** taper
        t = t0 + (t1 - t0) * f
        if i == segs:
            rows.append((g.vert(p), None, t))
        else:
            rows.append((g.vert(p - w * wd * 0.5), g.vert(p + w * wd * 0.5), t))
        step = d * math.sin(ang) + UP * math.cos(ang)
        p = p + step * (length / segs)
        ang += curve / segs
    for i in range(segs):
        a0, a1, ta = rows[i]
        b0, b1, tb = rows[i + 1]
        if b1 is None:
            g.face((a0, a1, b0), ((u, ta), (u, ta), (u, tb)))
        else:
            g.face((a0, a1, b1, b0), ((u, ta), (u, ta), (u, tb), (u, tb)))
    return p


def frond(g, base, yaw, length, width, lean, curve, segs, col, t0=0.1, t1=1.0):
    """A fern frond: an arching strip folded along its midrib, with a serrated outline. 4*segs triangles."""
    d = Vector((math.cos(yaw), math.sin(yaw), 0.0))
    w = Vector((-math.sin(yaw), math.cos(yaw), 0.0))
    p = Vector(base)
    ang = lean
    u = ramp_u(col)
    rows = []
    for i in range(segs + 1):
        f = i / float(segs)
        shape = math.sin(math.pi * min(1.0, 0.12 + f * 0.95)) ** 0.7        # narrow at the base, widest at 40 %, pointed tip
        serr = 1.0 if i % 2 == 0 else 0.62
        wd = width * shape * serr * (0.0 if i == segs else 1.0)
        step = d * math.sin(ang) + UP * math.cos(ang)
        side_up = step.cross(w).normalized()                                  # frond's own "up"
        t = t0 + (t1 - t0) * f
        mid = g.vert(p)
        if i == segs:
            rows.append((mid, mid, mid, t))
        else:
            lift = side_up * (-wd * 0.28)
            rows.append((g.vert(p - w * wd * 0.5 - lift), mid, g.vert(p + w * wd * 0.5 - lift), t))
        p = p + step * (length / segs)
        ang += curve / segs
    for i in range(segs):
        l0, m0, r0, ta = rows[i]
        l1, m1, r1, tb = rows[i + 1]
        te = min(1.0, tb + 0.12)
        if i == segs - 1:
            g.face((l0, m0, m1), ((u, ta), (u, ta * 0.8), (u, 1.0)))
            g.face((m0, r0, m1), ((u, ta * 0.8), (u, ta), (u, 1.0)))
        else:
            g.face((l0, m0, m1, l1), ((u, te), (u, ta * 0.8), (u, tb * 0.8), (u, te)))
            g.face((m0, r0, r1, m1), ((u, ta * 0.8), (u, te), (u, te), (u, tb * 0.8)))


def stalk(g, p0, p1, r0, r1, col, t0, t1, sides=3):
    axis = (Vector(p1) - Vector(p0)).normalized()
    side = axis.cross(UP)
    if side.length < 1e-3:
        side = Vector((1, 0, 0))
    side.normalize()
    other = axis.cross(side)
    u = ramp_u(col)
    ring0, ring1 = [], []
    for k in range(sides):
        a = 2 * math.pi * k / sides
        o = side * math.cos(a) + other * math.sin(a)
        ring0.append(g.vert(Vector(p0) + o * r0))
        ring1.append(g.vert(Vector(p1) + o * r1))
    for k in range(sides):
        k2 = (k + 1) % sides
        g.face((ring0[k], ring0[k2], ring1[k2], ring1[k]), ((u, t0), (u, t0), (u, t1), (u, t1)))


def bulb(g, centre, axis, radius, length, col, t0, t1, sides=4):
    """A stretched bipyramid: 2*sides triangles."""
    axis = Vector(axis).normalized()
    side = axis.cross(UP)
    if side.length < 1e-3:
        side = Vector((1, 0, 0))
    side.normalize()
    other = axis.cross(side)
    c = Vector(centre)
    u = ramp_u(col)
    bottom = g.vert(c - axis * length * 0.42)
    top = g.vert(c + axis * length * 0.58)
    ring = []
    for k in range(sides):
        a = 2 * math.pi * (k + 0.5) / sides
        ring.append(g.vert(c + (side * math.cos(a) + other * math.sin(a)) * radius))
    tm = t0 + (t1 - t0) * 0.45
    for k in range(sides):
        k2 = (k + 1) % sides
        g.face((bottom, ring[k2], ring[k]), ((u, t0), (u, tm), (u, tm)))
        g.face((ring[k], ring[k2], top), ((u, tm), (u, tm), (u, t1)))


_ICO = {}


def ico(sub):
    if sub not in _ICO:
        bm = bmesh.new()
        bmesh.ops.create_icosphere(bm, subdivisions=sub, radius=1.0)
        bm.verts.index_update()
        _ICO[sub] = ([v.co.copy() for v in bm.verts], [tuple(v.index for v in f.verts) for f in bm.faces])
        bm.free()
    return _ICO[sub]


def tube(g, pts, radii, sides, v_scale=0.5, u_rep=1.0, cap=True, v0=0.0, spin=0.0):
    """A bent tube mapped onto the bark region of the atlas (wraps once around, tiles along its length)."""
    rings = []
    length = 0.0
    prev_side = None
    for i, p in enumerate(pts):
        p = Vector(p)
        if i == 0:
            axis = (Vector(pts[1]) - p)
        elif i == len(pts) - 1:
            axis = (p - Vector(pts[i - 1]))
        else:
            axis = (Vector(pts[i + 1]) - Vector(pts[i - 1]))
        axis.normalize()
        if prev_side is None:
            side = axis.cross(UP)
            if side.length < 1e-3:
                side = Vector((1, 0, 0))
        else:
            side = prev_side - axis * prev_side.dot(axis)
        side.normalize()
        prev_side = side
        other = axis.cross(side)
        if i > 0:
            length += (p - Vector(pts[i - 1])).length
        ring = []
        for k in range(sides):
            a = 2 * math.pi * k / sides + spin
            ring.append(g.vert(p + (side * math.cos(a) + other * math.sin(a)) * radii[i]))
        rings.append((ring, v0 + length * v_scale))
    for i in range(len(rings) - 1):
        (r0, va), (r1, vb) = rings[i], rings[i + 1]
        for k in range(sides):
            k2 = (k + 1) % sides
            ua = BARK_U0 + (1.0 - BARK_U0) * (k / float(sides)) * u_rep
            ub = BARK_U0 + (1.0 - BARK_U0) * ((k + 1) / float(sides)) * u_rep
            g.face((r0[k], r0[k2], r1[k2], r1[k]), ((ua, va), (ub, va), (ub, vb), (ua, vb)))
    if cap:
        ring, vv = rings[-1]
        tip = g.vert(Vector(pts[-1]) + (Vector(pts[-1]) - Vector(pts[-2])).normalized() * radii[-1] * 0.8)
        for k in range(sides):
            k2 = (k + 1) % sides
            ua = BARK_U0 + (1.0 - BARK_U0) * (k / float(sides)) * u_rep
            ub = BARK_U0 + (1.0 - BARK_U0) * ((k + 1) / float(sides)) * u_rep
            g.face((ring[k], ring[k2], tip), ((ua, vv), (ub, vv), ((ua + ub) * 0.5, vv + radii[-1] * v_scale)))
    return rings


def make_ucx(owner, points, max_points=20, shrink=1.0):
    """One convex hull from the support points of `points` in evenly spread directions."""
    pts = [Vector(p) for p in points]
    chosen = {}
    n = max_points
    for i in range(n):
        z = 1.0 - 2.0 * (i + 0.5) / n
        r = math.sqrt(max(0.0, 1.0 - z * z))
        a = i * math.pi * (3.0 - math.sqrt(5.0))
        d = Vector((r * math.cos(a), r * math.sin(a), z))
        best = max(range(len(pts)), key=lambda k: pts[k].dot(d))
        chosen[best] = pts[best]
    bm = bmesh.new()
    for p in chosen.values():
        bm.verts.new(p * shrink)
    res = bmesh.ops.convex_hull(bm, input=list(bm.verts))
    junk = [e for e in res.get("geom_interior", []) + res.get("geom_unused", []) if isinstance(e, bmesh.types.BMVert)]
    if junk:
        bmesh.ops.delete(bm, geom=junk, context="VERTS")
    me = bpy.data.meshes.new("UCX_" + owner.name)
    bm.to_mesh(me)
    bm.free()
    obj = bpy.data.objects.new("UCX_" + owner.name + "_00", me)
    bpy.context.scene.collection.objects.link(obj)
    obj.parent = owner
    obj.display_type = "WIRE"
    obj.hide_render = False
    return obj


# ---------------------------------------------------------------------------------------------- ground cover
def grass_tuft(name, seed, mat, blades, patch, h_lo, h_hi, width, col, segs, curve, alt_col=None):
    rng = random.Random(seed)
    g = Geo()
    for i in range(blades):
        # sunflower layout, jittered: even coverage of the patch, denser in the middle
        r = patch * math.sqrt((i + 0.5) / blades) * rng.uniform(0.8, 1.05)
        a = i * 2.39996 + rng.uniform(-0.3, 0.3)
        base = Vector((r * math.cos(a), r * math.sin(a), -0.04))
        fall = 1.0 - 0.35 * (r / patch)
        h = rng.uniform(h_lo, h_hi) * fall
        yaw = a + rng.uniform(-0.9, 0.9)
        c = col if alt_col is None or rng.random() > 0.3 else alt_col
        blade(g, base, yaw, h, width * rng.uniform(0.75, 1.25), rng.uniform(0.10, 0.45) + 0.35 * (r / patch),
              curve * rng.uniform(0.5, 1.4), segs, c, 0.0, rng.uniform(0.8, 1.0), face_yaw=rng.uniform(0, math.pi))
    return g.build(name, mat, smooth=False, up_blend=0.75), g.tris()


def fern_tuft(name, seed, mat):
    rng = random.Random(seed)
    g = Geo()
    n = 11
    for i in range(n):
        yaw = 2 * math.pi * i / n + rng.uniform(-0.25, 0.25)
        inner = i % 3 == 0
        length = rng.uniform(0.55, 0.7) if inner else rng.uniform(0.9, 1.2)
        frond(g, (0.05 * math.cos(yaw), 0.05 * math.sin(yaw), -0.03), yaw, length, length * 0.26,
              0.25 if inner else rng.uniform(0.55, 0.8), rng.uniform(0.9, 1.3), 4, 2)
    return g.build(name, mat, smooth=False, up_blend=0.6), g.tris()


def glow_bulbs(name, seed, mat):
    """Cyan: a clump of thin stalks, each ending in a glowing pod, over a skirt of dark leaves."""
    rng = random.Random(seed)
    g = Geo()
    for i in range(8):
        r = 0.42 * math.sqrt((i + 0.5) / 8.0)
        a = i * 2.39996 + rng.uniform(-0.3, 0.3)
        base = Vector((r * math.cos(a), r * math.sin(a), -0.04))
        h = rng.uniform(0.35, 0.95) * (1.0 - 0.3 * r / 0.42)
        lean = Vector((math.cos(a), math.sin(a), 0.0)) * rng.uniform(0.05, 0.3) * h
        mid = base + UP * h * 0.55 + lean * 0.4
        top = base + UP * h + lean
        stalk(g, base, mid, 0.014, 0.010, 3, 0.0, 0.3)
        stalk(g, mid, top, 0.010, 0.008, 3, 0.3, 0.55)
        size = rng.uniform(0.045, 0.075)
        bulb(g, top + (top - mid).normalized() * size * 0.9, (top - mid), size, size * 3.2, 3, 0.62, 1.0)
    for i in range(7):
        yaw = 2 * math.pi * i / 7 + rng.uniform(-0.3, 0.3)
        blade(g, (0.06 * math.cos(yaw), 0.06 * math.sin(yaw), -0.03), yaw, rng.uniform(0.3, 0.45), 0.11, 0.7, 0.9, 2, 3, 0.0, 0.5)
    return g.build(name, mat, smooth=False, up_blend=0.3), g.tris()


def glow_stars(name, seed, mat):
    """Violet: low star flowers with a glowing heart, on a mat of dark leaves."""
    rng = random.Random(seed)
    g = Geo()
    u = ramp_u(4)
    for i in range(6):
        r = 0.55 * math.sqrt((i + 0.5) / 6.0)
        a = i * 2.39996 + rng.uniform(-0.3, 0.3)
        h = rng.uniform(0.10, 0.32)
        base = Vector((r * math.cos(a), r * math.sin(a), -0.03))
        c = base + UP * h + Vector((math.cos(a), math.sin(a), 0)) * 0.05
        stalk(g, base, c, 0.016, 0.012, 4, 0.0, 0.45)
        size = rng.uniform(0.13, 0.22)
        centre = g.vert(c)
        petals = 6
        spin = rng.uniform(0, 1)
        for k in range(petals):
            a0 = 2 * math.pi * (k - 0.5) / petals + spin
            a1 = 2 * math.pi * (k + 0.5) / petals + spin
            am = 2 * math.pi * k / petals + spin
            v0 = g.vert(c + Vector((math.cos(a0), math.sin(a0), 0.25)) * size * 0.42)
            v1 = g.vert(c + Vector((math.cos(a1), math.sin(a1), 0.25)) * size * 0.42)
            tip = g.vert(c + Vector((math.cos(am), math.sin(am), 0.45)) * size)
            g.face((centre, v0, tip, v1), ((u, 1.0), (u, 0.72), (u, 0.5), (u, 0.72)))
        bulb(g, c + UP * size * 0.22, UP, size * 0.13, size * 0.55, 4, 0.8, 1.0, sides=3)
    for i in range(6):
        yaw = 2 * math.pi * i / 6 + rng.uniform(-0.3, 0.3)
        blade(g, (0.1 * math.cos(yaw), 0.1 * math.sin(yaw), -0.03), yaw, rng.uniform(0.35, 0.6), 0.16, 1.1, 0.5, 2, 4, 0.0, 0.5)
    return g.build(name, mat, smooth=False, up_blend=0.3), g.tris()


# ---------------------------------------------------------------------------------------------- canopy
def canopy_clump(name, seed, mat, crowns, spread, r_lo, r_hi, h_lo, h_hi, cyan_share, lobes):
    """Several tree crowns merged into one mass for the far ring; a dark trunk under each.
    A crown is one large lump plus a few small ones, faceted, so the mass reads as foliage and not as balloons."""
    rng = random.Random(seed)
    g = Geo()
    big = ico(2)
    small = ico(1)
    placed = []
    for i in range(crowns):
        for _ in range(40):
            a = rng.uniform(0, 2 * math.pi)
            r = spread * math.sqrt(rng.random()) if i else 0.0
            c = Vector((r * math.cos(a), r * math.sin(a), 0.0))
            rad = rng.uniform(r_lo, r_hi) * (1.15 if i == 0 else 1.0)
            if all((c - q).length > (rad + qr) * 0.42 for q, qr in placed):
                break
        placed.append((c, rad))
        top = rng.uniform(h_lo, h_hi) * (1.12 if i == 0 else 1.0)
        thick = min(rad * rng.uniform(0.75, 0.95), top * 0.34)
        centre = Vector((c.x, c.y, top - thick))
        u = ramp_u(5 if rng.random() < cyan_share else 6)
        z_lo, z_hi = centre.z - thick * 0.9, top + thick * 0.1
        lumps = [(big, centre, rad, thick)]
        for k in range(lobes):
            ang = 2 * math.pi * (k + rng.random()) / max(1, lobes)
            lr = rad * rng.uniform(0.42, 0.6)
            off = Vector((math.cos(ang), math.sin(ang), 0.0)) * rad * rng.uniform(0.55, 0.8)
            lumps.append((small, centre + off + UP * thick * rng.uniform(-0.45, 0.5), lr, lr * 0.85))
        for (verts, faces), lc, lrad, lthick in lumps:
            noff = Vector((rng.uniform(0, 50), rng.uniform(0, 50), rng.uniform(0, 50)))
            idx, ts = [], []
            for v in verts:
                lump = 1.0 + 0.30 * noise.noise(v * 1.7 + noff) + 0.18 * noise.noise(v * 4.3 + noff)
                sz = lthick * (1.0 if v.z > 0 else 0.85)
                p = lc + Vector((v.x * lrad * lump, v.y * lrad * lump, v.z * sz * lump))
                idx.append(g.vert(p))
                t = (p.z - z_lo) / max(0.01, z_hi - z_lo)
                ts.append(min(0.98, max(0.02, t + 0.10 * noise.noise(v * 3.0 + noff))))
            for f in faces:
                g.face([idx[k] for k in f], [(u, ts[k]) for k in f])
        # trunk: a three-sided post from below the ground into the crown, flared at the foot
        ub = ramp_u(7)
        tr = max(0.9, rad * 0.13)
        rings = []
        spin = rng.uniform(0, 1)
        for z, k in ((-3.0, 1.9), (centre.z * 0.25, 1.0), (centre.z, 0.8)):
            rings.append([g.vert(Vector((c.x, c.y, z)) + Vector((math.cos(2 * math.pi * j / 3 + spin), math.sin(2 * math.pi * j / 3 + spin), 0)) * tr * k)
                          for j in range(3)])
        for r0, r1 in zip(rings, rings[1:]):
            for j in range(3):
                j2 = (j + 1) % 3
                g.face((r0[j], r0[j2], r1[j2], r1[j]), ((ub, 0.1), (ub, 0.1), (ub, 0.9), (ub, 0.9)))
    return g.build(name, mat, smooth=False), g.tris()


# ---------------------------------------------------------------------------------------------- boulders
def rock_chunk(bm, seed, size, centre, cuts, lump=0.22, tilt=(0, 0, 0), sub=3):
    rng = random.Random(seed)
    verts, faces = ico(sub)
    off = Vector((rng.uniform(0, 80), rng.uniform(0, 80), rng.uniform(0, 80)))
    rot = Matrix.Rotation(tilt[2], 4, "Z") @ Matrix.Rotation(tilt[1], 4, "Y") @ Matrix.Rotation(tilt[0], 4, "X")
    tmp = bmesh.new()
    new = []
    for v in verts:
        k = 1.0 + lump * noise.noise(v * 1.3 + off) + lump * 0.45 * noise.noise(v * 3.1 + off)
        new.append(tmp.verts.new(v * k))
    for f in faces:
        tmp.faces.new([new[i] for i in f])
    # flat facets: slice the lump with planes, which is what makes it read as broken rock, not a potato
    for i in range(cuts):
        d = Vector((rng.uniform(-1, 1), rng.uniform(-1, 1), rng.uniform(-0.5, 1.0))).normalized()
        dist = rng.uniform(0.62, 0.9)
        geom = list(tmp.verts) + list(tmp.edges) + list(tmp.faces)
        res = bmesh.ops.bisect_plane(tmp, geom=geom, plane_co=d * dist, plane_no=d, clear_outer=True)
        edges = [e for e in res["geom_cut"] if isinstance(e, bmesh.types.BMEdge)]
        if edges:
            bmesh.ops.contextual_create(tmp, geom=edges)
    half = Vector(size) * 0.5
    for v in tmp.verts:
        p = Vector((v.co.x * half.x, v.co.y * half.y, v.co.z * half.z))
        v.co = (rot @ p) + Vector(centre)
    me = bpy.data.meshes.new("__chunk__")
    tmp.to_mesh(me)
    tmp.free()
    bm.from_mesh(me)
    bpy.data.meshes.remove(me)


def boulder(name, seed, mat, chunks, sink):
    bm = bmesh.new()
    for i, (size, centre, cuts, tilt) in enumerate(chunks):
        rock_chunk(bm, seed * 31 + i, size, centre, cuts, tilt=tilt, sub=3 if i == 0 else 2)
    # ground the piece: drop its lowest point `sink` below z = 0, then cut the underside flat just below that
    low = min(v.co.z for v in bm.verts)
    for v in bm.verts:
        v.co.z -= low + sink
    geom = list(bm.verts) + list(bm.edges) + list(bm.faces)
    res = bmesh.ops.bisect_plane(bm, geom=geom, plane_co=(0, 0, -sink * 0.6), plane_no=(0, 0, -1), clear_outer=True)
    edges = [e for e in res["geom_cut"] if isinstance(e, bmesh.types.BMEdge)]
    if edges:
        bmesh.ops.contextual_create(bm, geom=edges)
    # centre the footprint on the pivot
    xs = [v.co.x for v in bm.verts]
    ys = [v.co.y for v in bm.verts]
    cx, cy = (min(xs) + max(xs)) * 0.5, (min(ys) + max(ys)) * 0.5
    for v in bm.verts:
        v.co.x -= cx
        v.co.y -= cy
    bmesh.ops.remove_doubles(bm, verts=list(bm.verts), dist=0.01)
    bmesh.ops.dissolve_degenerate(bm, edges=list(bm.edges), dist=0.01)
    bmesh.ops.triangulate(bm, faces=list(bm.faces))
    bmesh.ops.recalc_face_normals(bm, faces=list(bm.faces))
    uv = bm.loops.layers.uv.new("UVMap")
    for f in bm.faces:
        n = f.normal
        for loop in f.loops:
            p = loop.vert.co
            if abs(n.z) > 0.6:
                loop[uv].uv = (p.x * 0.2, p.y * 0.2)
            elif abs(n.x) > abs(n.y):
                loop[uv].uv = (p.y * 0.2, p.z * 0.2)
            else:
                loop[uv].uv = (p.x * 0.2, p.z * 0.2)
    me = bpy.data.meshes.new(name)
    bm.to_mesh(me)
    pts = [v.co.copy() for v in bm.verts]
    tris = len(bm.faces)
    bm.free()
    me.materials.append(mat)
    me.shade_smooth()
    me.set_sharp_from_angle(angle=math.radians(32))
    obj = bpy.data.objects.new(name, me)
    bpy.context.scene.collection.objects.link(obj)
    make_ucx(obj, pts, max_points=24)
    return obj, tris


# ---------------------------------------------------------------------------------------------- charred trees
def char_tree(name, seed, mat, height, base_r, lean, branches, snapped):
    rng = random.Random(seed)
    g = Geo()
    # trunk: flared root, a lean and two kinks
    n = 8
    pts, radii = [], []
    lean_dir = Vector((math.cos(lean[0]), math.sin(lean[0]), 0.0))
    for i in range(n + 1):
        f = i / float(n)
        z = -0.35 + (height + 0.35) * f
        wob = Vector((rng.uniform(-1, 1), rng.uniform(-1, 1), 0.0)) * 0.10 * height * 0.12 * (1 if 0 < i < n else 0)
        pts.append(lean_dir * lean[1] * height * f * f + wob + UP * z)
        flare = 1.0 + 0.7 * max(0.0, 1.0 - f * 6.0) ** 2
        radii.append(base_r * flare * (1.0 - 0.72 * f ** 0.9))
    if snapped:
        radii[-1] = radii[-2] * 0.75
    tube(g, pts, radii, 7, v_scale=0.33, cap=True)
    trunk_pts = [p.copy() for p in pts]
    # branches: bare, kinked, each with one or two twigs
    for b in range(branches):
        f = 0.38 + 0.55 * (b + rng.uniform(0.1, 0.9)) / branches
        seg = min(n - 1, int(f * n))
        t = f * n - seg
        origin = pts[seg].lerp(pts[seg + 1], t)
        r0 = (radii[seg] * (1 - t) + radii[seg + 1] * t) * 0.62
        yaw = 2.39996 * b + rng.uniform(-0.5, 0.5) + seed
        out = Vector((math.cos(yaw), math.sin(yaw), 0.0))
        length = height * rng.uniform(0.22, 0.38) * (1.15 - 0.4 * f)
        rise = rng.uniform(0.35, 0.9)
        p1 = origin + (out + UP * rise).normalized() * length * 0.5
        bend = Vector((math.cos(yaw + rng.uniform(-0.9, 0.9)), math.sin(yaw + rng.uniform(-0.9, 0.9)), 0.0))
        p2 = p1 + (bend + UP * rng.uniform(0.5, 1.4)).normalized() * length * 0.5
        tube(g, [origin - out * r0 * 0.5, p1, p2], [r0, r0 * 0.6, r0 * 0.22], 4, v_scale=0.33, u_rep=0.5, cap=True, v0=rng.random())
        for _ in range(1 if b % 2 else 2):
            tyaw = yaw + rng.uniform(-1.4, 1.4)
            tdir = (Vector((math.cos(tyaw), math.sin(tyaw), 0.0)) + UP * rng.uniform(0.3, 1.2)).normalized()
            start = p1.lerp(p2, rng.uniform(0.0, 0.6))
            tube(g, [start, start + tdir * length * rng.uniform(0.3, 0.5)], [r0 * 0.3, r0 * 0.08], 3, v_scale=0.33, u_rep=0.25,
                 cap=False, v0=rng.random())
    obj = g.build(name, mat, smooth=True, sharp_deg=50)
    hull_pts = []
    for p, r in zip(trunk_pts, radii):
        if p.z <= 2.6:
            for k in range(6):
                a = 2 * math.pi * k / 6
                hull_pts.append(p + Vector((math.cos(a), math.sin(a), 0.0)) * r * 0.9)
    make_ucx(obj, hull_pts, max_points=16)
    return obj, g.tris()


# ---------------------------------------------------------------------------------------------- the kit
def clear_scene():
    for o in list(bpy.data.objects):
        bpy.data.objects.remove(o, do_unlink=True)
    for me in list(bpy.data.meshes):
        if me.users == 0:
            bpy.data.meshes.remove(me)


def build_all(atlas_mat, rock_mat):
    R = math.radians
    out = []

    def add(obj_tris, group, collision, nanite, material, note):
        obj, tris = obj_tris
        out.append({"name": obj.name, "obj": obj, "tris": tris, "group": group, "collision": collision, "nanite": nanite,
                    "material": material, "note": note})

    # --- Verdance ground cover (near ring). Two-sided, no collision, no shadow.
    add(grass_tuft("SM_Scatter_Verd_Grass_01", 11, atlas_mat, blades=48, patch=0.9, h_lo=0.30, h_hi=0.60, width=0.15, col=0, segs=2, curve=1.0),
        "groundcover", "none", False, "MI_Scatter_Foliage", "broad-bladed teal grass patch")
    add(grass_tuft("SM_Scatter_Verd_Grass_02", 12, atlas_mat, blades=36, patch=0.65, h_lo=0.75, h_hi=1.40, width=0.10, col=1, segs=3, curve=0.8, alt_col=0),
        "groundcover", "none", False, "MI_Scatter_Foliage", "tall reeds with violet tips")
    add(fern_tuft("SM_Scatter_Verd_Fern_01", 13, atlas_mat),
        "groundcover", "none", False, "MI_Scatter_Foliage", "low fern rosette")
    add(glow_bulbs("SM_Scatter_Verd_GlowFlora_01", 14, atlas_mat),
        "groundcover", "none", False, "MI_Scatter_Foliage", "cyan glowing pods on stalks")
    add(glow_stars("SM_Scatter_Verd_GlowFlora_02", 15, atlas_mat),
        "groundcover", "none", False, "MI_Scatter_Foliage", "violet glowing star flowers")

    # --- Verdance canopy clumps (mid and far ring).
    add(canopy_clump("SM_Scatter_Verd_Canopy_01", 21, atlas_mat, crowns=5, spread=15.0, r_lo=8.0, r_hi=12.0, h_lo=20.0, h_hi=28.0, cyan_share=0.8, lobes=3),
        "canopy", "none", True, "MI_Scatter_Canopy", "5 lobed crowns, mostly cyan, 20 to 30 m tall")
    add(canopy_clump("SM_Scatter_Verd_Canopy_02", 22, atlas_mat, crowns=7, spread=22.0, r_lo=9.0, r_hi=15.0, h_lo=24.0, h_hi=38.0, cyan_share=0.45, lobes=1),
        "canopy", "none", True, "MI_Scatter_Canopy", "7 crowns, cyan and pink mixed, 25 to 40 m tall")
    add(canopy_clump("SM_Scatter_Verd_Canopy_03", 23, atlas_mat, crowns=9, spread=30.0, r_lo=10.0, r_hi=18.0, h_lo=28.0, h_hi=48.0, cyan_share=0.6, lobes=0),
        "canopy", "none", True, "MI_Scatter_Canopy", "9 crowns with one emergent giant, up to 55 m tall")

    # --- Boulders (both planets; tint by material instance).
    add(boulder("SM_Scatter_Any_Boulder_01", 31, rock_mat, [
        ((4.6, 3.6, 3.4), (0, 0, 0), 7, (R(8), R(-6), 0.3)),
        ((2.2, 1.9, 1.5), (2.0, 0.9, -0.8), 5, (R(-15), R(10), 1.0))], sink=0.35),
        "boulder", "ucx", True, "MI_Scatter_Rock_Verdance", "4.5 m rounded block with a spall")
    add(boulder("SM_Scatter_Any_Boulder_02", 32, rock_mat, [
        ((7.0, 5.0, 4.6), (0, 0, 0), 8, (R(-10), R(12), 0.8)),
        ((3.4, 3.0, 2.4), (-3.0, 1.6, -1.0), 6, (R(20), R(5), 2.0)),
        ((2.0, 1.8, 1.4), (2.8, -2.2, -1.5), 5, (R(5), R(-20), 0.4))], sink=0.45),
        "boulder", "ucx", True, "MI_Scatter_Rock_Verdance", "7 m boulder with two fallen pieces")
    add(boulder("SM_Scatter_Any_Boulder_03", 33, rock_mat, [
        ((10.5, 5.6, 4.2), (0, 0, 0.6), 8, (R(22), R(-8), 0.2)),
        ((5.5, 4.4, 3.2), (2.6, 2.6, -1.0), 7, (R(-12), R(14), 1.4)),
        ((3.0, 2.4, 1.8), (-4.2, -1.8, -1.2), 5, (R(10), R(18), 2.6))], sink=0.5),
        "boulder", "ucx", True, "MI_Scatter_Rock_Verdance", "10 m leaning slab propped on a block")
    add(boulder("SM_Scatter_Any_Boulder_04", 34, rock_mat, [
        ((8.5, 7.5, 10.5), (0, 0, 0), 9, (R(7), R(-9), 0.5)),
        ((6.0, 5.0, 6.0), (4.0, -2.0, -2.2), 8, (R(-14), R(10), 1.1)),
        ((4.2, 3.8, 3.2), (-3.6, 3.2, -3.4), 6, (R(18), R(6), 2.2)),
        ((2.4, 2.0, 1.6), (1.0, 5.0, -4.2), 5, (R(-8), R(-16), 0.7))], sink=0.6),
        "boulder", "ucx", True, "MI_Scatter_Rock_Verdance", "12 m crag: a tall tooth with a pile at its foot")

    # --- Cinder charred trees.
    add(char_tree("SM_Scatter_Cind_CharTree_01", 41, atlas_mat, height=7.2, base_r=0.34, lean=(0.6, 0.16), branches=7, snapped=False),
        "chartree", "ucx", False, "MI_Scatter_Char", "7 m dead tree, five bare branches")
    add(char_tree("SM_Scatter_Cind_CharTree_02", 42, atlas_mat, height=4.4, base_r=0.42, lean=(3.9, 0.10), branches=4, snapped=True),
        "chartree", "ucx", False, "MI_Scatter_Char", "4.5 m snapped trunk, three stubs")
    return out


def lay_out(items):
    """Row them up by group so the review sheets frame each group on its own."""
    x = {"groundcover": 0.0, "canopy": 0.0, "boulder": 0.0, "chartree": 0.0}
    y = {"groundcover": 0.0, "canopy": 200.0, "boulder": 500.0, "chartree": 700.0}
    for it in items:
        obj = it["obj"]
        bpy.context.view_layer.update()
        w = max(obj.dimensions.x, obj.dimensions.y)
        obj.location = (x[it["group"]] + w * 0.5, y[it["group"]], 0.0)
        x[it["group"]] += w * 1.15 + 0.2


def figure(at):
    """A 1.8 m stand-in pilot for scale in the review sheets (never exported)."""
    g = Geo()
    u = ramp_u(7)
    def box(lo, hi):
        vs = [g.vert((x, y, z)) for z in (lo[2], hi[2]) for y in (lo[1], hi[1]) for x in (lo[0], hi[0])]
        for f in ((0, 1, 3, 2), (4, 6, 7, 5), (0, 4, 5, 1), (1, 5, 7, 3), (3, 7, 6, 2), (2, 6, 4, 0)):
            g.face([vs[k] for k in f], [(u, 0.9)] * 4)
    box((-0.2, -0.12, 0.0), (0.2, 0.12, 0.85))
    box((-0.25, -0.14, 0.85), (0.25, 0.14, 1.5))
    box((-0.11, -0.11, 1.55), (0.11, 0.11, 1.8))
    obj = g.build("SRC_Figure_180cm", bpy.data.materials["M_Scatter_Atlas"])
    obj.location = at
    return obj


def main():
    clear_scene()
    os.makedirs(REVIEW, exist_ok=True)
    paths = build_atlas()
    atlas_mat, rock_mat = make_materials(paths)
    items = build_all(atlas_mat, rock_mat)
    lay_out(items)
    bpy.context.view_layer.update()

    export = runpy.run_path(os.path.join(SKILLS, "blender-unreal-export", "scripts", "export_for_unreal.py"))
    report = runpy.run_path(os.path.join(SKILLS, "blender-mcp", "scripts", "asset_report.py"))
    review = runpy.run_path(os.path.join(SKILLS, "blender-mcp", "scripts", "review_renders.py"))
    summary = []
    for it in items:
        name = it["name"]
        folder = os.path.join(KIT, name)
        os.makedirs(folder, exist_ok=True)
        try:
            export["main"](root=name, out_dir=folder, front_axis="+X",
                           collision="auto" if it["collision"] == "ucx" else "none", textures_dir=TEX_DIR)
        except AttributeError:
            # The exporter's last step (restoring the selection) trips over a stale view-layer entry when run
            # headless on a scene built in the same script. The FBX and manifest are already written by then.
            bpy.context.view_layer.update()
        man_path = os.path.join(folder, name + ".manifest.json")
        with open(man_path, encoding="utf-8") as fh:
            manifest = json.load(fh)
        manifest["fbx"] = name + ".fbx"          # relative: manifests are read from any checkout
        manifest["textures"] = [] if it["group"] == "boulder" else ["T_Scatter_Atlas_BC.png", "T_Scatter_Atlas_E.png"]
        manifest["nanite_recommended"] = it["nanite"]
        manifest["unreal_import"]["nanite"] = it["nanite"]
        manifest["scatter"] = {"group": it["group"], "collision": it["collision"], "material_instance": it["material"],
                               "two_sided": it["group"] == "groundcover", "note": it["note"]}
        with open(man_path, "w", encoding="utf-8") as fh:
            json.dump(manifest, fh, indent=2)
        rep = report["main"](targets=[name])
        family = {it["obj"], *it["obj"].children_recursive}
        datablocks = set(family)
        bpy.data.libraries.write(os.path.join(folder, name + ".blend"), datablocks, compress=True)
        dims = it["obj"].dimensions
        summary.append({"asset": name, "tris": manifest["tris"], "size_cm": manifest["size_cm"], "collision": manifest["collision"],
                        "group": it["group"], "issues": rep.get("issues", [])[:6],
                        "dims_m": [round(dims.x, 2), round(dims.y, 2), round(dims.z, 2)]})

    # review sheets, one per group, with the 1.8 m figure beside the first asset
    sheets = []
    for group in ("groundcover", "canopy", "boulder", "chartree"):
        names = [it["name"] for it in items if it["group"] == group]
        first = bpy.data.objects[names[0]]
        fig = figure((first.location.x - first.dimensions.x * 0.5 - 0.6, first.location.y, 0.0))
        bpy.context.view_layer.update()
        for mode in ("material", "clay"):
            res = review["main"](targets=names + [fig.name], out_dir=REVIEW, label="scatter_%s_%s" % (group, mode), mode=mode,
                                 views=["front_3q", "front", "top"], resolution=640, columns=3)
            sheets.append(res.get("contact_sheet") or res.get("sheet") or str(res)[:200])
        bpy.data.objects.remove(fig, do_unlink=True)
    with open(os.path.join(REVIEW, "summary.json"), "w", encoding="utf-8") as fh:
        json.dump({"assets": summary, "sheets": sheets}, fh, indent=2)
    print("__RESULT__" + json.dumps({"assets": summary, "sheets": sheets}))


main()
